class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:
        intervals = sorted(intervals, key=lambda x: x[1])
        removed = 0
        prev_end = intervals[0][1]
        for s, e in intervals[1:]:
            if s < prev_end:
                removed += 1
            else:
                prev_end = e
        return removed
